--
-- Table structure for table `exercises`
--

DROP TABLE IF EXISTS `exercises`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `exercises` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `category` enum('cardio','strength','flexibility','balance','sports') NOT NULL,
  `exercise_category_id` int(11) DEFAULT NULL,
  `muscle_groups` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Array of muscle groups' CHECK (json_valid(`muscle_groups`)),
  `equipment` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Array of equipment needed' CHECK (json_valid(`equipment`)),
  `difficulty` enum('beginner','intermediate','advanced') NOT NULL,
  `instructions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Array of instruction steps' CHECK (json_valid(`instructions`)),
  `tips` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Array of tips' CHECK (json_valid(`tips`)),
  `video_url` varchar(255) DEFAULT NULL,
  `image_url` varchar(255) DEFAULT NULL,
  `duration` int(11) DEFAULT NULL COMMENT 'Duration in minutes',
  `calories_per_minute` float DEFAULT NULL,
  `is_custom` tinyint(1) DEFAULT 0,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `created_by` (`created_by`),
  KEY `idx_exercises_exercise_category` (`exercise_category_id`),
  CONSTRAINT `exercises_ibfk_1` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_exercises_exercise_category` FOREIGN KEY (`exercise_category_id`) REFERENCES `exercise_categories` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=63 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `exercises`
--

LOCK TABLES `exercises` WRITE;
/*!40000 ALTER TABLE `exercises` DISABLE KEYS */;
INSERT INTO `exercises` VALUES (1,'Push-ups','Classic upper body exercise','strength',NULL,'[\"Triceps\",\"Deltoids\"]','[\"None\"]','beginner','[]','[]','https://www.youtube.com/shorts/LBcQJFyDrr0','https://images.squarespace-cdn.com/content/v1/58501b0cf5e23149e5589e12/1585601917653-J791ZN5ZWSK565NIZSS1/1_WZmDgcJO40Va5mVgdfbz7g%402x.jpeg',0,7,0,NULL,'2025-11-25 09:14:35','2025-11-25 17:13:21'),(2,'Squats','Lower body compound exercise','strength',NULL,'[\"Hamstrings\",\"Calves\"]','[]','beginner','[]','[]','https://res.cloudinary.com/dqqkwg3aa/video/upload/v1764065898/fitness-app/exercises/squats/zfxzezgibchl9h3b3oit.mp4','https://images.squarespace-cdn.com/content/v1/58501b0cf5e23149e5589e12/1585601917653-J791ZN5ZWSK565NIZSS1/1_WZmDgcJO40Va5mVgdfbz7g%402x.jpeg',0,8,0,NULL,'2025-11-25 09:29:31','2025-11-25 10:18:20'),(3,'Running','Running is an effective exercise that enhances strength, conditioning, mobility, or endurance depending on execution.','cardio',NULL,'[\"Triceps\",\"Full Body\"]','[\"Dumbbell\"]','beginner','[\"1. Start in the proper setup position for Running.\",\"2. Engage your core to stabilize your spine.\",\"3. Perform the main movement with full control and balanced form.\",\"4. Maintain steady breathing, exhaling during exertion.\",\"5. Return to the starting position slowly.\",\"6. Repeat for the programmed reps or duration.\"]','[\"- Keep proper form throughout Running to prevent injury.\",\"- Do not rush; prioritize control over speed.\",\"- Increase resistance gradually for better progress.\"]','https://youtube.com/results?search_query=Running+exercise','https://placeholder.com/Running.jpg',15,11,0,NULL,'2025-11-25 09:29:31','2025-11-25 13:01:33'),(4,'Plank','Core stability exercise','strength',NULL,'[\"Shoulders\",\"Glutes\"]','[\"None\"]','beginner','[\"Get into forearm plank position\",\"Keep body straight from head to heels\",\"Hold position\"]','[\"Don\'t let hips sag\",\"Keep core engaged\",\"Breathe steadily\"]','https://www.youtube.com/shorts/LBcQJFyDrr0','https://images.squarespace-cdn.com/content/v1/58501b0cf5e23149e5589e12/1585601917653-J791ZN5ZWSK565NIZSS1/1_WZmDgcJO40Va5mVgdfbz7g%402x.jpeg',30,5,0,NULL,'2025-11-25 09:29:31','2025-11-25 09:37:26'),(5,'Bicep Curls','Arm isolation exercise','strength',NULL,'[\"Forearms\"]','[\"Dumbbells\"]','beginner','[\"Stand with dumbbells at sides\",\"Curl weights up to shoulders\",\"Lower with control\"]','[\"Keep elbows stationary\",\"Don\'t swing weights\",\"Control the movement\"]','https://www.youtube.com/shorts/LBcQJFyDrr0','https://images.squarespace-cdn.com/content/v1/58501b0cf5e23149e5589e12/1585601917653-J791ZN5ZWSK565NIZSS1/1_WZmDgcJO40Va5mVgdfbz7g%402x.jpeg',0,6,0,NULL,'2025-11-25 09:29:31','2025-11-25 09:37:26'),(6,'Hip Opener','Hip Opener is an effective exercise that enhances strength, conditioning, mobility, or endurance depending on execution.','',NULL,'[\"Triceps\"]','[\"Barbell\"]','beginner','[\"1. Start in the proper setup position for Hip Opener.\",\"2. Engage your core to stabilize your spine.\",\"3. Perform the main movement with full control and balanced form.\",\"4. Maintain steady breathing, exhaling during exertion.\",\"5. Return to the starting position slowly.\",\"6. Repeat for the programmed reps or duration.\"]','[\"- Keep proper form throughout Hip Opener to prevent injury.\",\"- Do not rush; prioritize control over speed.\",\"- Increase resistance gradually for better progress.\"]','https://youtube.com/results?search_query=Hip+Opener+exercise','https://placeholder.com/Hip_Opener.jpg',20,3,0,NULL,'2025-11-25 12:15:37','2025-11-25 13:01:32'),(7,'Chest Fly','Chest Fly is an effective exercise designed to improve performance, strength, and overall conditioning.','strength',NULL,'[\"Glutes\"]','[\"Kettlebell\"]','advanced','[\"Stand or start in the proper starting position for the Chest Fly.\",\"Engage your core and maintain a stable posture throughout the movement.\",\"Perform the main action of the exercise with controlled movement and full range of motion.\",\"Focus on breathing: inhale during preparation and exhale during exertion.\",\"Return to the starting position slowly while keeping proper form.\",\"Repeat the movement until the required reps or duration is completed.\"]','[\"Keep your form strict during Chest Fly to avoid injury.\",\"Start with light resistance and gradually increase as you get stronger.\",\"Avoid rushing the movement; slow, controlled reps work best.\"]','https://youtube.com/results?search_query=Chest+Fly+exercise','https://placeholder.com/Chest_Fly.jpg',0,7,0,NULL,'2025-11-25 12:15:37','2025-11-25 12:16:25'),(8,'Cycling','Cycling is an effective exercise that enhances strength, conditioning, mobility, or endurance depending on execution.','cardio',NULL,'[\"Shoulders\",\"Biceps\"]','[\"Barbell\"]','beginner','[\"1. Start in the proper setup position for Cycling.\",\"2. Engage your core to stabilize your spine.\",\"3. Perform the main movement with full control and balanced form.\",\"4. Maintain steady breathing, exhaling during exertion.\",\"5. Return to the starting position slowly.\",\"6. Repeat for the programmed reps or duration.\"]','[\"- Keep proper form throughout Cycling to prevent injury.\",\"- Do not rush; prioritize control over speed.\",\"- Increase resistance gradually for better progress.\"]','https://youtube.com/results?search_query=Cycling+exercise','https://placeholder.com/Cycling.jpg',15,12,0,NULL,'2025-11-25 12:15:38','2025-11-25 13:01:33'),(9,'Sprint Intervals','Sprint Intervals is an effective exercise that enhances strength, conditioning, mobility, or endurance depending on execution.','',NULL,'[\"Chest\",\"Forearms\",\"Biceps\"]','[\"Barbell\"]','beginner','[\"1. Start in the proper setup position for Sprint Intervals.\",\"2. Engage your core to stabilize your spine.\",\"3. Perform the main movement with full control and balanced form.\",\"4. Maintain steady breathing, exhaling during exertion.\",\"5. Return to the starting position slowly.\",\"6. Repeat for the programmed reps or duration.\"]','[\"- Keep proper form throughout Sprint Intervals to prevent injury.\",\"- Do not rush; prioritize control over speed.\",\"- Increase resistance gradually for better progress.\"]','https://youtube.com/results?search_query=Sprint+Intervals+exercise','https://placeholder.com/Sprint_Intervals.jpg',0,15,0,NULL,'2025-11-25 12:15:38','2025-11-25 13:01:33'),(10,'Shoulder Stretch','Shoulder Stretch is an effective exercise that enhances strength, conditioning, mobility, or endurance depending on execution.','flexibility',NULL,'[\"Forearms\"]','[\"Kettlebell\"]','advanced','[\"1. Start in the proper setup position for Shoulder Stretch.\",\"2. Engage your core to stabilize your spine.\",\"3. Perform the main movement with full control and balanced form.\",\"4. Maintain steady breathing, exhaling during exertion.\",\"5. Return to the starting position slowly.\",\"6. Repeat for the programmed reps or duration.\"]','[\"- Keep proper form throughout Shoulder Stretch to prevent injury.\",\"- Do not rush; prioritize control over speed.\",\"- Increase resistance gradually for better progress.\"]','https://youtube.com/results?search_query=Shoulder+Stretch+exercise','https://placeholder.com/Shoulder_Stretch.jpg',30,4,0,NULL,'2025-11-25 12:15:38','2025-11-25 13:01:33'),(11,'Jump Squats','Jump Squats is an effective exercise that enhances strength, conditioning, mobility, or endurance depending on execution.','',NULL,'[\"Abs\",\"Shoulders\",\"Glutes\"]','[\"Kettlebell\"]','intermediate','[\"1. Start in the proper setup position for Jump Squats.\",\"2. Engage your core to stabilize your spine.\",\"3. Perform the main movement with full control and balanced form.\",\"4. Maintain steady breathing, exhaling during exertion.\",\"5. Return to the starting position slowly.\",\"6. Repeat for the programmed reps or duration.\"]','[\"- Keep proper form throughout Jump Squats to prevent injury.\",\"- Do not rush; prioritize control over spe