DROP TABLE IF EXISTS `food_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `food_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `food_name` varchar(255) NOT NULL,
  `brand` varchar(255) DEFAULT NULL,
  `barcode` varchar(255) DEFAULT NULL COMMENT 'Barcode if scanned from product',
  `meal_type` enum('breakfast','lunch','dinner','snack') NOT NULL DEFAULT 'snack',
  `serving_size` varchar(255) DEFAULT '100g',
  `serving_amount` float NOT NULL DEFAULT 1 COMMENT 'Number of servings consumed',
  `calories` int(11) NOT NULL DEFAULT 0,
  `protein` float NOT NULL DEFAULT 0,
  `carbs` float NOT NULL DEFAULT 0,
  `fat` float NOT NULL DEFAULT 0,
  `fiber` float DEFAULT 0,
  `sugar` float DEFAULT 0,
  `sodium` float DEFAULT 0,
  `image_url` varchar(255) DEFAULT NULL,
  `ingredients` text DEFAULT NULL,
  `log_date` date NOT NULL COMMENT 'Date when food was consumed',
  `log_time` time DEFAULT NULL COMMENT 'Time when food was consumed',
  `notes` text DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `food_logs_user_id_log_date` (`user_id`,`log_date`),
  KEY `food_logs_barcode` (`barcode`),
  CONSTRAINT `food_logs_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

