--
-- Table structure for table `meal_plans`
--

DROP TABLE IF EXISTS `meal_plans`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `meal_plans` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `name` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `duration` int(11) NOT NULL COMMENT 'Duration in days',
  `start_date` datetime NOT NULL,
  `end_date` datetime NOT NULL,
  `meals` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Array of meals for each day' CHECK (json_valid(`meals`)),
  `total_calories` int(11) DEFAULT NULL,
  `macronutrients` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Total macronutrients for the plan' CHECK (json_valid(`macronutrients`)),
  `dietary_restrictions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Array of dietary restrictions' CHECK (json_valid(`dietary_restrictions`)),
  `preferences` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'User preferences' CHECK (json_valid(`preferences`)),
  `is_active` tinyint(1) DEFAULT 1,
  `ai_generated` tinyint(1) DEFAULT 0,
  `ai_prompt` text DEFAULT NULL COMMENT 'AI prompt used to generate this plan',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `meal_plans_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `meal_plans`
--

LOCK TABLES `meal_plans` WRITE;
/*!40000 ALTER TABLE `meal_plans` DISABLE KEYS */;
INSERT INTO `meal_plans` VALUES (1,1,'AI-Generated Daily Meal Plan','Personalized meal plan based on your profile (BMI: 20.83, Level: Normal)',1,'2025-11-25 11:06:22','2025-11-26 11:06:22','{\"breakfast\":{\"name\":\"Tofu Scramble with Mixed Veggies & Whole-Wheat Toast\",\"time\":\"7:30 AM\",\"description\":\"A protein-rich and flavorful tofu scramble packed with recommended vegetables, served with a slice of whole-wheat toast for sustained energy.\",\"foods\":[{\"name\":\"Firm Tofu, crumbled\",\"amount\":\"200g\",\"calories\":160},{\"name\":\"Mixed Bell Peppers (red, yellow, green), diced\",\"amount\":\"70g\",\"calories\":20},{\"name\":\"Fresh Spinach\",\"amount\":\"70g\",\"calories\":14},{\"name\":\"Cherry Tomatoes, halved\",\"amount\":\"70g\",\"calories\":13},{\"name\":\"Celery, diced\",\"amount\":\"50g\",\"calories\":8},{\"name\":\"Olive Oil\",\"amount\":\"1.5 tsp (7.5ml)\",\"calories\":68},{\"name\":\"Whole Wheat Toast\",\"amount\":\"1 slice (30g)\",\"calories\":80},{\"name\":\"Spices (turmeric, black pepper, salt to taste)\",\"amount\":\"As needed\",\"calories\":0}],\"totalCalories\":363,\"macros\":{\"protein\":26.8,\"carbs\":30,\"fat\":16.5},\"instructions\":[\"Press tofu to remove excess water, then crumble it into a pan.\",\"Heat olive oil in a non-stick pan over medium heat.\",\"Add bell peppers and celery, sauté for 3-5 minutes until slightly tender.\",\"Add crumbled tofu, spinach, and cherry tomatoes. Season with turmeric, black pepper, and salt.\",\"Cook for another 5-7 minutes, stirring occasionally, until spinach is wilted and tofu is lightly browned.\",\"Serve hot with one slice of whole-wheat toast.\"]},\"lunch\":{\"name\":\"Vietnamese-Inspired Grilled Chicken & Quinoa Salad\",\"time\":\"12:30 PM\",\"description\":\"A refreshing and protein-packed salad featuring lean grilled chicken, nutrient-dense quinoa, and a vibrant mix of fresh vegetables with a light, zesty vinaigrette.\",\"foods\":[{\"name\":\"Grilled Chicken Breast, skinless\",\"amount\":\"150g\",\"calories\":240},{\"name\":\"Cooked Quinoa\",\"amount\":\"100g\",\"calories\":120},{\"name\":\"Mixed Greens (e.g., lettuce, baby spinach)\",\"amount\":\"100g\",\"calories\":15},{\"name\":\"Cherry Tomatoes, halved\",\"amount\":\"70g\",\"calories\":13},{\"name\":\"Cucumber, sliced\",\"amount\":\"100g\",\"calories\":15},{\"name\":\"Mixed Bell Peppers, sliced\",\"amount\":\"70g\",\"calories\":20},{\"name\":\"Carrots, shredded\",\"amount\":\"50g\",\"calories\":20},{\"name\":\"Celery, chopped\",\"amount\":\"50g\",\"calories\":8},{\"name\":\"Light Vinaigrette (olive oil, rice vinegar, a squeeze of lime, salt, pepper)\",\"amount\":\"1.5 tbsp\",\"calories\":90},{\"name\":\"Fresh Herbs (cilantro, mint, for garnish)\",\"amount\":\"As needed\",\"calories\":0}],\"totalCalories\":541,\"macros\":{\"protein\":53,\"carbs\":42,\"fat\":18},\"instructions\":[\"Grill or pan-sear chicken breast until fully cooked and lightly browned, then slice.\",\"In a large bowl, combine mixed greens, cherry tomatoes, cucumber, bell peppers, shredded carrots, and chopped celery.\",\"Add cooked quinoa and sliced grilled chicken to the salad.\",\"Drizzle with light vinaigrette and toss gently to combine.\",\"Garnish with fresh herbs if desired.\"]},\"snack\":{\"name\":\"Green Power Juice with Almonds\",\"time\":\"3:30 PM\",\"description\":\"A revitalizing green juice, rich in vitamins and minerals, paired with a small handful of almonds for healthy fats and sustained energy.\",\"foods\":[{\"name\":\"Green Juice (blend of Kale, Spinach, Cucumber, Celery, Green Apple)\",\"amount\":\"Approx. 350ml (from specified ingredients)\",\"calories\":110},{\"name\":\"Almonds\",\"amount\":\"25g (approx. 20-22 pieces)\",\"calories\":144}],\"totalCalories\":254,\"macros\":{\"protein\":9.4,\"carbs\":29.5,\"fat\":12.7},\"instructions\":[\"Wash all produce thoroughly.\",\"Juice kale, spinach, cucumber, celery, and green apple using a juicer. If using a blender, add a small amount of water, blend until smooth, and strain if preferred.\",\"Pour juice into a glass and enjoy immediately with the portion of almonds.\"]},\"dinner\":{\"name\":\"Steamed Fish with Stir-fried Mixed Vegetables & Brown Rice\",\"time\":\"7:00 PM\",\"description\":\"A light and wholesome Vietnamese-inspired dinner featuring tender steamed white fish, a colorful stir-fry of recommended vegetables, and a serving of nutrient-rich brown rice.\",\"foods\":[{\"name\":\"White Fish Fillet (e.g., Tilapia, Cod, Basa)\",\"amount\":\"200g\",\"calories\":200},{\"name\":\"Cooked Brown Rice\",\"amount\":\"120g\",\"calories\":150},{\"name\":\"Mixed Bell Peppers, sliced\",\"amount\":\"100g\",\"calories\":25},{\"name\":\"Carrots, julienned\",\"amount\":\"70g\",\"calories\":28},{\"name\":\"Celery, sliced diagonally\",\"amount\":\"70g\",\"calories\":11},{\"name\":\"Green Beans, trimmed\",\"amount\":\"70g\",\"calories\":22},{\"name\":\"Low-Sodium Soy Sauce\",\"amount\":\"1 tbsp\",\"calories\":8},{\"name\":\"Fresh Ginger, grated\",\"amount\":\"1 tsp\",\"calories\":2},{\"name\":\"Garlic, minced\",\"amount\":\"1 clove\",\"calories\":4},{\"name\":\"Sesame Oil\",\"amount\":\"1 tsp (5ml)\",\"calories\":45}],\"totalCalories\":495,\"macros\":{\"protein\":46.7,\"carbs\":54,\"fat\":10.5},\"instructions\":[\"Season fish fillet with a pinch of salt, pepper, and some grated ginger.\",\"Steam the fish for 10-15 minutes, or until cooked through and flaky.\",\"While fish is steaming, heat sesame oil in a wok or large pan over medium-high heat.\",\"Add minced garlic and the remaining grated ginger, stir-fry for 30 seconds until fragrant.\",\"Add bell peppers, carrots, celery, and green beans to the pan. Stir-fry for 5-7 minutes until vegetables are tender-crisp.\",\"Stir in low-sodium soy sauce. Remove from heat.\",\"Serve the steamed fish immediately with the stir-fried vegetables and cooked brown rice.\"]},\"totalDailyCalories\":1653,\"totalDailyMacros\":{\"protein\":135.9,\"carbs\":155.5,\"fat\":57.7},\"notes\":[\"Consistency is key for weight loss. Stick to the meal plan as much as possible.\",\"Feel free to swap protein sources (chicken, fish, tofu, legumes) within meals, ensuring similar portion sizes for calorie and macro consistency.\",\"Preparation methods like steaming, grilling, baking, and stir-frying with minimal oil are encouraged over deep-frying.\",\"Listen to your body\'s hunger and fullness cues. Adjust portion sizes slightly if you feel excessively hungry or full, while staying mindful of your overall calorie goal.\",\"This plan is a template; you can vary the specific types of recommended vegetables and herbs to keep meals interesting.\"],\"hydration\":\"Drink at least 2.5 to 3 liters (approximately 10-12 glasses) of water throughout the day. Hydration is crucial for metabolism and overall well-being, especially with a cardio fitness routine.\"}',1653,'{\"protein\":135.9,\"carbs\":155.5,\"fat\":57.7}','[]','{}',1,1,'ML Diet Recommendation: Vegetables: (Mixed greens, cherry tomatoes, cucumbers, bell peppers, carrots, celery, bell peppers);Protein Intake: (Chicken, fish, tofu, or legumes); Juice : (Green juice,kale, spinach, cucumber, cel...','2025-11-25 11:06:22','2025-11-25 11:06:22'),(2,1,'AI-Generated Daily Meal Plan','Personalized meal plan based on your profile (BMI: 20.83, Level: Normal)',1,'2025-11-25 11:42:27','2025-11-26 11:42:27','{\"breakfast\":{\"name\":\"Hearty Tofu Scramble with Veggies & Whole Grain Toast\",\"time\":\"7:00 AM\",\"description\":\"A protein-rich and nutrient-dense start to your day, featuring plant-based protein and a variety of colorful vegetables.\",\"foods\":[{\"name\":\"Firm Tofu, crumbled\",\"amount\":\"180g\",\"calories\":156},{\"name\":\"Mixed Bell Peppers & Onion, diced\",\"amount\":\"100g\",\"calories\":30},{\"name\":\"Fresh Spinach\",\"amount\":\"50g\",\"calories\":12},{\"name\":\"Cherry Tomatoes, halved\",\"amount\":\"50g\",\"calories\":10},{\"name\":\"Olive Oil\",\"amount\":\"1.5 tsp (7.5ml)\",\"calories\":60},{\"name\":\"Whole-Wheat Toast\",\"amount\":\"2 slices (80g)\",\"calories\":200}],\"totalCalories\":468,\"macros\":{\"protein\":28.5,\"carbs\":49,\"fat\":20},\"instructions\":[\"Heat olive oil in a non-stick pan over medium heat.\",\"Add diced bell peppers and onion; sauté for 3-5 minutes until softened.\",\"Crumble tofu into the pan and cook for 5-7 minutes, stirring occasionally, until slightly golden.\",\"Stir in spinach and cherry tomatoes, cook until spinach wilts (1-2 minutes). Season with a pinch of salt and pepper.\",\"Serve the tofu scramble alongside two slices of whole-wheat toast.\"]},\"lunch\":{\"name\":\"Vietnamese-inspired Grilled Fish Salad with Brown Rice\",\"time\":\"12:30 PM\",\"description\":\"A light and refreshing salad with lean grilled fish, crisp vegetables, and a flavorful dressing, served with wholesome brown rice.\",\"foods\":[{\"name\":\"Grilled White Fish (e.g., Tilapia, Cod)\",\"amount\":\"150g\",\"calories\":160},{\"name\":\"Mixed Greens\",\"amount\":\"150g\",\"calories\":23},{\"name\":\"Cucumber, sliced\",\"amount\":\"75g\",\"calories\":12},{\"name\":\"Shredded Carrots\",\"amount\":\"75g\",\"calories\":30},{\"name\":\"Bell Peppers (various colors), sliced\",\"amount\":\"75g\",\"calories\":23},{\"name\":\"Light Vietnamese-style Dressing (lime juice, fish sauce, a touch of honey, 1 tsp olive oil)\",\"amount\":\"2 tbsp\",\"calories\":50},{\"name\":\"Cooked Brown Rice\",\"amount\":\"1 cup (180g)\",\"calories\":220}],\"totalCalories\":518,\"macros\":{\"protein\":39.6,\"carbs\":70.5,\"fat\":9},\"instructions\":[\"Season the fish with a pinch of salt and pepper. Grill or pan-sear until cooked through and flaky (about 3-4 minutes per side).\",\"In a large bowl, combine mixed greens, cucumber, shredded carrots, and sliced bell peppers.\",\"Prepare the dressing by whisking together lime juice, a dash of fish sauce, a tiny touch of honey or agave, and olive oil.\",\"Place the grilled fish on top of the salad. Drizzle with the dressing.\",\"Serve immediately with a side of cooked brown rice.\"]},\"snack\":{\"name\":\"Refreshing Green Juice\",\"time\":\"3:00 PM\",\"description\":\"A revitalizing green juice packed with essential vitamins and minerals, perfect for an afternoon energy boost.\",\"foods\":[{\"name\":\"Kale\",\"amount\":\"1 cup (67g)\",\"calories\":30},{\"name\":\"Spinach\",\"amount\":\"1 cup (30g)\",\"calories\":7},{\"name\":\"Cucumber\",\"amount\":\"1/2 medium (100g)\",\"calories\":15},{\"name\":\"Celery Stalks\",\"amount\":\"2 large (80g)\",\"calories\":13},{\"name\":\"Small Apple\",\"amount\":\"1 (100g)\",\"calories\":50},{\"name\":\"Water\",\"amount\":\"as needed\",\"calories\":0}],\"totalCalories\":115,\"macros\":{\"protein\":4.6,\"carbs\":28,\"fat\":0},\"instructions\":[\"Wash all ingredients thoroughly.\",\"Chop kale, spinach, cucumber, celery, and apple into smaller pieces suitable for your juicer.\",\"Process all ingredients through a juicer.\",\"If desired, add a splash of water to adjust consistency.\",\"Pour into a glass and enjoy immediately.\"]},\"dinner\":{\"name\":\"Lean Chicken & Veggie Stir-fry with Brown Rice\",\"time\":\"7:00 PM\",\"description\":\"A wholesome and satisfying stir-fry featuring lean chicken breast and a generous medley of vegetables, served with fiber-rich brown rice.\",\"foods\":[{\"name\":\"Chicken Breast, skinless, diced\",\"amount\":\"150g\",\"calories\":206},{\"name\":\"Broccoli florets\",\"amount\":\"100g\",\"calories\":35},{\"name\":\"Carrots, sliced\",\"amount\":\"50g\",\"calories\":20},{\"name\":\"Bell Peppers (any color), sliced\",\"amount\":\"50g\",\"calories\":15},{\"name\":\"Celery, sliced\",\"amount\":\"50g\",\"calories\":8},{\"name\":\"Low-Sodium Soy Sauce\",\"amount\":\"1 tbsp\",\"calories\":10},{\"name\":\"Fresh Ginger, grated\",\"amount\":\"1 tsp\",\"calories\":5},{\"name\":\"Garlic, minced\",\"amount\":\"1 clove\",\"calories\":5},{\"name\":\"Sesame Oil\",\"amount\":\"1 tsp\",\"calories\":40},{\"name\":\"Cooked Brown Rice\",\"amount\":\"1 cup (180g)\",\"calories\":220}],\"totalCalories\":564,\"macros\":{\"protein\":46.3,\"carbs\":71,\"fat\":11},\"instructions\":[\"Heat sesame oil in a large wok or skillet over medium-high heat.\",\"Add diced chicken breast and stir-fry until cooked through and lightly browned (about 5-7 minutes). Remove chicken from the pan and set aside.\",\"Add ginger and garlic to the pan, stir-fry for 30 seconds until fragrant.\",\"Add broccoli, carrots, bell peppers, and celery to the pan. Stir-fry for 5-7 minutes until vegetables are tender-crisp.\",\"Return the cooked chicken to the pan. Add low-sodium soy sauce and toss everything together to coat.\",\"Serve the chicken and veggie stir-fry immediately with a side of cooked brown rice.\"]},\"totalDailyCalories\":1665,\"totalDailyMacros\":{\"protein\":119,\"carbs\":218.5,\"fat\":40},\"notes\":[\"This meal plan is designed for weight loss, aiming for a caloric deficit while providing adequate nutrients for your cardio fitness routine.\",\"Ensure you listen to your body and adjust portion sizes slightly if you feel overly hungry or too full.\",\"The recommended vegetables and proteins from the ML model are incorporated throughout the day to provide a diverse nutrient intake.\",\"Consistency is key for weight loss. Try to stick to regular meal times and prepare meals in advance if helpful.\",\"You can swap protein sources (chicken, fish, tofu, legumes) in meals, keeping the portion sizes similar, to maintain variety and adherence.\"],\"hydration\":\"Aim to drink at least 8-10 glasses (2-2.5 liters) of water throughout the day. Increase intake if engaging in intense cardio or in hot weather.\"}',1665,'{\"protein\":119,\"carbs\":218.5,\"fat\":40}','[]','{}',1,1,'ML Diet Recommendation: Vegetables: (Mixed greens, cherry tomatoes, cucumbers, bell peppers, carrots, celery, bell peppers);Protein Intake: (Chicken, fish, tofu, or legumes); Juice : (Green juice,kale, spinach, cucumber, cel...','2025-11-25 11:42:27','2025-11-25 11:42:27'),(3,3,'Thao\'s Lean & Strong: A 7-Day Balanced Nutrition Plan','This 7-day meal plan is designed for Thao Tran, focusing on achieving her goals of weight loss and muscle gain. It prioritizes high protein intake, complex carbohydrates, and healthy fats, spread across 4 balanced meals daily. The plan incorporates a delicious mix of international and Vietnamese cuisine, emphasizing fresh ingredients, easy preparation, and variety to keep meals enjoyable and sustainable.',7,'2025-11-25 16:47:32','2025-12-02 16:47:32','[{\"dayNumber\":1,\"date\":\"Day 1\",\"meals\":{\"breakfast\":{\"name\":\"Savory Scrambled Eggs with Spinach & Whole Wheat Toast\",\"time\":\"7:00 AM\",\"description\":\"A protein-rich start to the day with eggs and nutrient-dense spinach.\",\"foods\":[{\"name\":\"Large Eggs\",\"amount\":\"2\",\"calories\":156},{\"name\":\"Egg Whites\",\"amount\":\"2\",\"calories\":34},{\"name\":\"Fresh Spinach\",\"amount\":\"1 cup (30g)\",\"calories\":7},{\"name\":\"Cherry Tomatoes\",\"amount\":\"1/2 cup (60g)\",\"calories\":11},{\"name\":\"Whole Wheat Bread\",\"amount\":\"1 slice (35g)\",\"calories\":80},{\"name\":\"Olive Oil\",\"amount\":\"1 tsp (5ml)\",\"calories\":40}],\"totalCalories\":328,\"macros\":{\"protein\":26,\"carbs\":21,\"fat\":15},\"instructions\":[\"Heat olive oil in a non-stick pan over medium heat.\",\"Add spinach and tomatoes; sauté until spinach wilts (1-2 minutes).\",\"Whisk eggs and egg whites together in a bowl, season with salt and pepper.\",\"Pour egg mixture into the pan, scramble until cooked through.\",\"Serve with toasted whole wheat bread.\"]},\"lunch\":{\"name\":\"Grilled Chicken & Avocado Salad with Lime Vinaigrette\",\"time\":\"12:30 PM\",\"description\":\"A light yet satisfying salad packed with protein and healthy fats.\",\"foods\":[{\"name\":\"Grilled Chicken Breast\",\"amount\":\"120g\",\"calories\":198},{\"name\":\"Mixed Greens\",\"amount\":\"2 cups (60g)\",\"calories\":15},{\"name\":\"Cucumber\",\"amount\":\"1/2 cup sliced (50g)\",\"calories\":8},{\"name\":\"Bell Pepper\",\"amount\":\"1/2 cup chopped (75g)\",\"calories\":20},{\"name\":\"Cherry Tomatoes\",\"amount\":\"1/2 cup (60g)\",\"calories\":11},{\"name\":\"Avocado\",\"amount\":\"1/4 medium (50g)\",\"calories\":80},{\"name\":\"Lime Juice\",\"amount\":\"1 tbsp (15ml)\",\"calories\":4},{\"name\":\"Olive Oil\",\"amount\":\"1 tbsp (15ml)\",\"calories\":120},{\"name\":\"Dijon Mustard\",\"amount\":\"1 tsp (5g)\",\"calories\":5}],\"totalCalories\":461,\"macros\":{\"protein\":34,\"carbs\":17,\"fat\":30},\"instructions\":[\"Season chicken breast and grill or pan-fry until cooked through. Let rest and slice.\",\"Wash and prepare all vegetables. Combine mixed greens, cucumber, bell pepper, and cherry tomatoes in a large bowl.\",\"Add sliced chicken and avocado.\",\"For the dressing: Whisk together lime juice, olive oil, and Dijon mustard. Season with salt and pepper.\",\"Pour dressing over the salad and toss gently to combine.\"]},\"dinner\":{\"name\":\"Tofu & Vegetable Stir-fry with Brown Rice\",\"time\":\"7:00 PM\",\"description\":\"A flavorful and nutrient-dense vegan option, rich in protein and fiber.\",\"foods\":[{\"name\":\"Firm Tofu\",\"amount\":\"150g\",\"calories\":135},{\"name\":\"Brown Rice\",\"amount\":\"120g cooked\",\"calories\":133},{\"name\":\"Broccoli Florets\",\"amount\":\"1 cup (90g)\",\"calories\":31},{\"name\":\"Carrots\",\"amount\":\"1/2 cup sliced (60g)\",\"calories\":25},{\"name\":\"Bell Pepper\",\"amount\":\"1/2 cup chopped (75g)\",\"calories\":20},{\"name\":\"Soy Sauce (low sodium)\",\"amount\":\"1 tbsp (15ml)\",\"calories\":8},{\"name\":\"Ginger (grated)\",\"amount\":\"1 tsp (5g)\",\"calories\":4},{\"name\":\"Garlic (minced)\",\"amount\":\"1 clove (3g)\",\"calories\":4},{\"name\":\"Sesame Oil\",\"amount\":\"1 tsp (5ml)\",\"calories\":40}],\"totalCalories\":499,\"macros\":{\"protein\":22,\"carbs\":66,\"fat\":17},\"instructions\":[\"Press tofu to remove excess water, then cut into cubes.\",\"Cook brown rice according to package instructions.\",\"Heat sesame oil in a large wok or pan over medium-high heat.\",\"Add garlic and ginger, stir-fry for 30 seconds until fragrant.\",\"Add tofu and cook until lightly golden on all sides (5-7 minutes). Remove from pan.\",\"Add broccoli, carrots, and bell pepper to the pan. Stir-fry for 5-7 minutes until vegetables are tender-crisp.\",\"Return tofu to the pan. Add soy sauce and stir to combine.\",\"Serve hot with brown rice.\"]},\"snack\":{\"name\":\"Greek Yogurt with Mixed Berries\",\"time\":\"3:30 PM\",\"description\":\"A simple, high-protein snack to curb hunger.\",\"foods\":[{\"name\":\"Plain Greek Yogurt (0% fat)\",\"amount\":\"170g\",\"calories\":100},{\"name\":\"Mixed Berries (fresh or frozen)\",\"amount\":\"1/2 cup (75g)\",\"calories\":40}],\"totalCalories\":140,\"macros\":{\"protein\":18,\"carbs\":15,\"fat\":0},\"instructions\":[\"Combine Greek yogurt and mixed berries in a bowl.\"]}},\"dailyTotals\":{\"calories\":1428,\"protein\":100,\"carbs\":119,\"fat\":62}},{\"dayNumber\":2,\"date\":\"Day 2\",\"meals\":{\"breakfast\":{\"name\":\"Overnight Oats with Protein Powder & Chia Seeds\",\"time\":\"7:00 AM\",\"description\":\"A convenient and nutritious breakfast, ready to eat in the morning.\",\"foods\":[{\"name\":\"Rolled Oats\",\"amount\":\"1/2 cup (40g)\",\"calories\":150},{\"name\":\"Unsweetened Almond Milk\",\"amount\":\"1 cup (240ml)\",\"calories\":30},{\"name\":\"Whey Protein Powder (vanilla)\",\"amount\":\"1 scoop (30g)\",\"calories\":120},{\"name\":\"Chia Seeds\",\"amount\":\"1 tbsp (12g)\",\"calories\":60},{\"name\":\"Banana\",\"amount\":\"1/2 medium (60g)\",\"calories\":53}],\"totalCalories\":413,\"macros\":{\"protein\":34,\"carbs\":51,\"fat\":10},\"instructions\":[\"The night before: In a jar or container, combine rolled oats, almond milk, protein powder, and chia seeds. Stir well.\",\"Cover and refrigerate overnight.\",\"In the morning, top with sliced banana before serving.\"]},\"lunch\":{\"name\":\"Lean Beef Noodle Stir-fry (Bun Xao Gion style)\",\"time\":\"12:30 PM\",\"description\":\"A Vietnamese-inspired dish, focusing on lean protein and fresh vegetables with a smaller portion of noodles.\",\"foods\":[{\"name\":\"Lean Beef Sirloin\",\"amount\":\"120g\",\"calories\":216},{\"name\":\"Vermicelli Noodles (cooked)\",\"amount\":\"80g\",\"calories\":112},{\"name\":\"Broccoli Florets\",\"amount\":\"1 cup (90g)\",\"calories\":31},{\"name\":\"Carrots (julienned)\",\"amount\":\"1/2 cup (60g)\",\"calories\":25},{\"name\":\"Snap Peas\",\"amount\":\"1/2 cup (60g)\",\"calories\":20},{\"name\":\"Soy Sauce (low sodium)\",\"amount\":\"1 tbsp (15ml)\",\"calories\":8},{\"name\":\"Oyster Sauce (low sodium)\",\"amount\":\"1 tbsp (15ml)\",\"calories\":15},{\"name\":\"Garlic (minced)\",\"amount\":\"1 clove (3g)\",\"calories\":4},{\"name\":\"Olive Oil\",\"amount\":\"1 tsp (5ml)\",\"calories\":40}],\"totalCalories\":471,\"macros\":{\"protein\":34,\"carbs\":58,\"fat\":16},\"instructions\":[\"Slice beef very thinly. Cook vermicelli noodles according to package directions, drain, and set aside.\",\"Heat olive oil in a wok or large pan over high heat.\",\"Add garlic and stir-fry for 15 seconds. Add beef and stir-fry until almost cooked through (2-3 minutes). Remove beef and set aside.\",\"Add broccoli, carrots, and snap peas to the pan. Stir-fry for 4-5 minutes until tender-crisp.\",\"Return beef to the pan. Add cooked vermicelli noodles, soy sauce, and oyster sauce. Toss everything together until well combined and heated through.\",\"Serve immediately.\"]},\"dinner\":{\"name\":\"Baked Salmon with Roasted Asparagus & Sweet Potato\",\"time\":\"7:00 PM\",\"description\":\"A heart-healthy meal rich in omega-3s, fiber, and lean protein.\",\"foods\":[{\"name\":\"Salmon Fillet\",\"amount\":\"120g\",\"calories\":246},{\"name\":\"Sweet Potato\",\"amount\":\"1 medium (150g)\",\"calories\":129},{\"name\":\"Asparagus\",\"amount\":\"10 spears (120g)\",\"calories\":24},{\"name\":\"Olive Oil\",\"amount\":\"1.5 tbsp (22.5ml)\",\"calories\":180},{\"name\":\"Lemon Wedge\",\"amount\":\"1\",\"calories\":2}],\"totalCalories\":581,\"macros\":{\"protein\":30,\"carbs\":33,\"fat\":38},\"instructions\":[\"Preheat oven to 200°C (400°F).\",\"Wash and chop sweet potato into cubes. Toss with 1 tbsp olive oil, salt, and pepper. Spread on a baking sheet.\",\"Toss asparagus with 0.5 tbsp olive oil, salt, and pepper. Place on the same baking sheet.\",\"Bake sweet potato and asparagus for 15 minutes.\",\"Season salmon fillet with salt, pepper, and a squeeze of lemon juice. Add to the baking sheet and bake for another 12-15 minutes, or until salmon is cooked through and flaky.\",\"Serve immediately.\"]},\"snack\":{\"name\":\"Apple Slices with Almonds\",\"time\":\"3:30 PM\",\"description\":\"A simple and satisfying snack providing fiber and healthy fats.\",\"foods\":[{\"name\":\"Medium Apple\",\"amount\":\"1 (180g)\",\"calories\":95},{\"name\":\"Almonds\",\"amount\":\"1/4 cup (28g)\",\"calories\":160}],\"totalCalories\":255,\"macros\":{\"protein\":6,\"carbs\":35,\"fat\":14},\"instructions\":[\"Slice the apple and serve with almonds.\"]}},\"dailyTotals\":{\"calories\":1720,\"protein\":104,\"carbs\":177,\"fat\":78}},{\"dayNumber\":3,\"date\":\"Day 3\",\"meals\":{\"breakfast\":{\"name\":\"High Protein Smoothie\",\"time\":\"7:00 AM\",\"description\":\"A quick and nutrient-dense smoothie for a busy morning.\",\"foods\":[{\"name\":\"Whey Protein Powder (unflavored/vanilla)\",\"amount\":\"1.5 scoops (45g)\",\"calories\":180},{\"name\":\"Unsweetened Almond Milk\",\"amount\":\"1 cup (240ml)\",\"calories\":30},{\"name\":\"Frozen Spinach\",\"amount\":\"1 cup (90g)\",\"calories\":23},{\"name\":\"Banana\",\"amount\":\"1/2 medium (60g)\",\"calories\":53},{\"name\":\"Chia Seeds\",\"amount\":\"1 tbsp (12g)\",\"calories\":60},{\"name\":\"Peanut Butter (natural)\",\"amount\":\"1 tbsp (16g)\",\"calories\":95}],\"totalCalories\":441,\"macros\":{\"protein\":44,\"carbs\":39,\"fat\":16},\"instructions\":[\"Combine all ingredients in a blender. Blend until smooth and creamy. Add a splash more almond milk if needed for desired consistency.\"]},\"lunch\":{\"name\":\"Mediterranean Chickpea & Quinoa Bowl\",\"time\":\"12:30 PM\",\"description\":\"A vibrant and flavorful bowl packed with plant-based protein and fiber.\",\"foods\":[{\"name\":\"Cooked Quinoa\",\"amount\":\"150g\",\"calories\":190},{\"name\":\"Canned Chickpeas (rinsed & drained)\",\"amount\":\"1/2 cup (80g)\",\"calories\":120},{\"name\":\"Cucumber (diced)\",\"amount\":\"1/2 cup (50g)\",\"calories\":8},{\"name\":\"Cherry Tomatoes (halved)\",\"amount\":\"1/2 cup (60g)\",\"calories\":11},{\"name\":\"Red Onion (thinly sliced)\",\"amount\":\"1/4 cup (30g)\",\"calories\":12},{\"name\":\"Feta Cheese (crumbled)\",\"amount\":\"30g\",\"calories\":80},{\"name\":\"Kalamata Olives (sliced)\",\"amount\":\"5 olives (20g)\",\"calories\":45},{\"name\":\"Olive Oil\",\"amount\":\"1 tbsp (15ml)\",\"calories\":120},{\"name\":\"Lemon Juice\",\"amount\":\"1 tbsp (15ml)\",\"calories\":4}],\"totalCalories\":590,\"macros\":{\"protein\":22,\"carbs\":64,\"fat\":29},\"instructions\":[\"Combine cooked quinoa, chickpeas, cucumber, cherry tomatoes, red onion, feta cheese, and olives in a large bowl.\",\"In a small bowl, whisk together olive oil and lemon juice. Season with salt and pepper.\",\"Pour dressing over the bowl ingredients and toss gently to combine. Serve immediately or chill for later.\"]},\"dinner\":{\"name\":\"Ga Xao Xa Ot (Lemongrass Chili Chicken Stir-fry) with Brown Rice\",\"time\":\"7:00 PM\",\"description\":\"A fragrant Vietnamese stir-fry with lean chicken and plenty of aromatics.\",\"foods\":[{\"name\":\"Chicken Breast (sliced)\",\"amount\":\"120g\",\"calories\":198},{\"name\":\"Brown Rice\",\"amount\":\"120g cooked\",\"calories\":133},{\"name\":\"Bell Pepper (sliced)\",\"amount\":\"1 cup (150g)\",\"calories\":40},{\"name\":\"Onion (sliced)\",\"amount\":\"1/2 medium (60g)\",\"calories\":25},{\"name\":\"Lemongrass (minced)\",\"amount\":\"1 tbsp (10g)\",\"calories\":10},{\"name\":\"Chili Garlic Sauce\",\"amount\":\"1 tsp (5g)\",\"calories\":5},{\"name\":\"Fish Sauce\",\"amount\":\"1 tbsp (15ml)\",\"calories\":10},{\"name\":\"Olive Oil\",\"amount\":\"1 tsp (5ml)\",\"calories\":40}],\"totalCalories\":461,\"macros\":{\"protein\":34,\"carbs\":59,\"fat\":13},\"instructions\":[\"Cook brown rice according to package instructions.\",\"Heat olive oil in a wok or large pan over medium-high heat.\",\"Add lemongrass and stir-fry for 1 minute until fragrant.\",\"Add sliced chicken and cook until mostly browned (3-4 minutes).\",\"Add bell pepper and onion, stir-fry for 3-5 minutes until vegetables are tender-crisp.\",\"Stir in chili garlic sauce and fish sauce. Toss everything to coat and cook for another 1-2 minutes.\",\"Serve hot with brown rice.\"]},\"snack\":{\"name\":\"Hard-Boiled Eggs\",\"time\":\"3:30 PM\",\"description\":\"A quick and portable protein boost.\",\"foods\":[{\"name\":\"Large Hard-Boiled Eggs\",\"amount\":\"2\",\"calories\":156}],\"totalCalories\":156,\"macros\":{\"protein\":12,\"carbs\":1,\"fat\":10},\"instructions\":[\"Boil eggs until desired doneness (usually 7-10 minutes for hard-boiled). Peel and enjoy.\"]}},\"dailyTotals\":{\"calories\":1648,\"protein\":112,\"carbs\":163,\"fat\":68}},{\"dayNumber\":4,\"date\":\"Day 4\",\"meals\":{\"breakfast\":{\"name\":\"Avocado & Poached Eggs on Whole Wheat Toast\",\"time\":\"7:00 AM\",\"description\":\"A balanced breakfast with healthy fats, protein, and complex carbs.\",\"foods\":[{\"name\":\"Whole Wheat Bread\",\"amount\":\"1 slice (35g)\",\"calories\":80},{\"name\":\"Avocado\",\"amount\":\"1/2 medium (100g)\",\"calories\":160},{\"name\":\"Large Eggs (poached)\",\"amount\":\"2\",\"calories\":156}],\"totalCalories\":396,\"macros\":{\"protein\":19,\"carbs\":24,\"fat\":24},\"instructions\":[\"Toast the whole wheat bread.\",\"Mash avocado lightly and spread on toast. Season with salt and pepper.\",\"Poach eggs: Bring a pot of water to a gentle simmer. Crack eggs individually into small bowls. Gently slide eggs into the simmering water. Cook for 3-4 minutes for runny yolks.\",\"Carefully remove poached eggs with a slotted spoon and place on top of the avocado toast. Season with chili flakes if desired.\"]},\"lunch\":{\"name\":\"Fresh Shrimp & Chicken Spring Rolls (Goi Cuon) with Light Peanut Sauce\",\"time\":\"12:30 PM\",\"description\":\"Light and refreshing Vietnamese fresh spring rolls, packed with protein and vegetables.\",\"foods\":[{\"name\":\"Cooked Shrimp\",\"amount\":\"60g\",\"calories\":60},{\"name\":\"Cooked Chicken Breast (shredded)\",\"amount\":\"60g\",\"calories\":99},{\"name\":\"Rice Paper Wrappers\",\"amount\":\"3 sheets (30g)\",\"calories\":100},{\"name\":\"Vermicelli Noodles (cooked)\",\"amount\":\"30g\",\"calories\":42},{\"name\":\"Lettuce Leaves\",\"amount\":\"3 large\",\"calories\":5},{\"name\":\"Cucumber (julienned)\",\"amount\":\"1/4 cup (25g)\",\"calories\":4},{\"name\":\"Carrots (julienned)\",\"amount\":\"1/4 cup (25g)\",\"calories\":10},{\"name\":\"Fresh Mint & Basil\",\"amount\":\"small handful\",\"calories\":2},{\"name\":\"Peanut Butter (natural)\",\"amount\":\"1 tbsp (16g)\",\"calories\":95},{\"name\":\"Hoison Sauce\",\"amount\":\"1 tbsp (15g)\",\"calories\":25},{\"name\":\"Lime Juice\",\"amount\":\"1 tsp (5ml)\",\"calories\":1},{\"name\":\"Warm Water\",\"amount\":\"1 tbsp (15ml)\",\"calories\":0}],\"totalCalories\":443,\"macros\":{\"protein\":34,\"carbs\":44,\"fat\":17},\"instructions\":[\"Prepare all ingredients: Cook shrimp and shred chicken if not already done. Cook vermicelli noodles, drain and cool. Wash and dry lettuce, cucumber, carrots, mint, and basil.\",\"Set up a rolling station: a shallow dish of warm water for rice paper, and all fillings arranged.\",\"Dip one rice paper wrapper in warm water for 15-20 seconds until pliable. Lay flat on a clean surface.\",\"Arrange a piece of lettuce, a small amount of vermicelli, cucumber, carrots, mint, and basil in the center of the bottom half of the wrapper.\",\"Place a few shrimp halves and some shredded chicken on top. Fold the bottom edge of the wrapper over the fillings, then fold in the sides.\",\"Roll tightly from bottom to top, ensuring filling is secure. Repeat for remaining rolls.\",\"For the light peanut sauce: Whisk together peanut butter, hoisin sauce, lime juice, and warm water until smooth. Adjust consistency with more water if needed.\",\"Serve spring rolls immediately with peanut sauce.\"]},\"dinner\":{\"name\":\"Turkey Meatballs with Zucchini Noodles & Marinara\",\"time\":\"7:00 PM\",\"description\":\"A lean and low-carb alternative to pasta, high in protein and vegetables.\",\"foods\":[{\"name\":\"Ground Lean Turkey (93% lean)\",\"amount\":\"150g\",\"calories\":240},{\"name\":\"Zucchini\",\"amount\":\"1 medium (200g)\",\"calories\":34},{\"name\":\"Marinara Sauce (low sugar)\",\"amount\":\"1/2 cup (120ml)\",\"calories\":60},{\"name\":\"Parmesan Cheese (grated)\",\"amount\":\"1 tbsp (10g)\",\"calories\":40},{\"name\":\"Egg\",\"amount\":\"1 large\",\"calories\":78},{\"name\":\"Whole Wheat Breadcrumbs\",\"amount\":\"2 tbsp (15g)\",\"calories\":50},{\"name\":\"Olive Oil\",\"amount\":\"1 tsp (5ml)\",\"calories\":40}],\"totalCalories\":542,\"macros\":{\"protein\":40,\"carbs\":33,\"fat\":28},\"instructions\":[\"In a bowl, combine ground turkey, egg, breadcrumbs, salt, pepper, and a pinch of dried Italian herbs. Mix gently until just combined. Form into 8-10 meatballs.\",\"Heat olive oil in a non-stick pan over medium heat. Add meatballs and cook, turning occasionally, until browned on all sides and cooked through (about 8-10 minutes). Remove from pan.\",\"Add marinara sauce to the pan and bring to a simmer. Return meatballs to the sauce.\",\"While meatballs are simmering, use a spiralizer or vegetable peeler to create \'zoodles\' from the zucchini.\",\"Sauté zoodles in a separate pan for 2-3 minutes until just tender, or add directly to the marinara sauce with meatballs for the last 2 minutes.\",\"Serve meatballs and sauce over zucchini noodles, topped with grated Parmesan cheese.\"]},\"snack\":{\"name\":\"Cottage Cheese with Pineapple\",\"time\":\"3:30 PM\",\"description\":\"A high-protein, refreshing snack.\",\"foods\":[{\"name\":\"Cottage Cheese (low fat)\",\"amount\":\"150g\",\"calories\":120},{\"name\":\"Fresh Pineapple (diced)\",\"amount\":\"1/2 cup (80g)\",\"calories\":40}],\"totalCalories\":160,\"macros\":{\"protein\":20,\"carbs\":13,\"fat\":3},\"instructions\":[\"Combine cottage cheese and pineapple in a bowl.\"]}},\"dailyTotals\":{\"calories\":1541,\"protein\":113,\"carbs\":114,\"fat\":72}},{\"dayNumber\":5,\"date\":\"Day 5\",\"meals\":{\"breakfast\":{\"name\":\"Greek Yogurt Parfait with Granola & Fruit\",\"time\":\"7:00 AM\",\"description\":\"A layered breakfast offering protein, fiber, and natural sweetness.\",\"foods\":[{\"name\":\"Plain Greek Yogurt (0% fat)\",\"amount\":\"170g\",\"calories\":100},{\"name\":\"Low Sugar Granola\",\"amount\":\"1/4 cup (30g)\",\"calories\":120},{\"name\":\"Mixed Berries\",\"amount\":\"1/2 cup (75g)\",\"calories\":40},{\"name\":\"Honey\",\"amount\":\"1 tsp (7g)\",\"calories\":20}],\"totalCalories\":280,\"macros\":{\"protein\":18,\"carbs\":44,\"fat\":4},\"instructions\":[\"In a glass or bowl, layer Greek yogurt, granola, and mixed berries. Drizzle with honey.\"]},\"lunch\":{\"name\":\"Leftover Turkey Meatballs with Zucchini Noodles\",\"time\":\"12:30 PM\",\"description\":\"Enjoying the delicious leftovers from yesterday\'s dinner, perfect for meal prep!\",\"foods\":[{\"name\":\"Ground Lean Turkey Meatballs\",\"amount\":\"150g (cooked)\",\"calories\":240},{\"name\":\"Zucchini Noodles\",\"amount\":\"1 medium (200g)\",\"calories\":34},{\"name\":\"Marinara Sauce (low sugar)\",\"amount\":\"1/2 cup (120ml)\",\"calories\":60},{\"name\":\"Parmesan Cheese (grated)\",\"amount\":\"1 tbsp (10g)\",\"calories\":40}],\"totalCalories\":374,\"macros\":{\"protein\":37,\"carbs\":21,\"fat\":15},\"instructions\":[\"Reheat meatballs and sauce in a microwave or on the stovetop until hot.\",\"Lightly sauté zucchini noodles in a pan for 1-2 minutes until warmed through, or microwave briefly.\",\"Serve meatballs and sauce over zucchini noodles, topped with Parmesan cheese.\"]},\"dinner\":{\"name\":\"Canh Chua Ca (Vietnamese Sour Fish Soup) with Brown Rice\",\"time\":\"7:00 PM\",\"description\":\"A light and tangy Vietnamese soup, rich in lean protein and vegetables.\",\"foods\":[{\"name\":\"White Fish Fillet (e.g., Tilapia, Cod)\",\"amount\":\"120g\",\"calories\":130},{\"name\":\"Brown Rice\",\"amount\":\"120g cooked\",\"calories\":133},{\"name\":\"Pineapple Chunks\",\"amount\":\"1/2 cup (80g)\",\"calories\":40},{\"name\":\"Tomatoes (wedges)\",\"amount\":\"1/2 cup (60g)\",\"calories\":11},{\"name\":\"Okra (sliced)\",\"amount\":\"1/2 cup (80g)\",\"calories\":25},{\"name\":\"Bean Sprouts\",\"amount\":\"1/2 cup (40g)\",\"calories\":15},{\"name\":\"Tamarind Paste\",\"amount\":\"1 tbsp (15g)\",\"calories\":25},{\"name\":\"Fish Sauce\",\"amount\":\"1 tbsp (15ml)\",\"calories\":10},{\"name\":\"Vegetable Broth\",\"amount\":\"2 cups (480ml)\",\"calories\":30},{\"name\":\"Fresh Herbs (cilantro, culantro)\",\"amount\":\"small handful\",\"calories\":2},{\"name\":\"Chili (optional)\",\"amount\":\"1\",\"calories\":4}],\"totalCalories\":465,\"macros\":{\"protein\":28,\"carbs\":79,\"fat\":5},\"instructions\":[\"Bring vegetable broth to a simmer in a pot. Add tamarind paste and fish sauce, stir until dissolved. Taste and adjust sour/salty to your preference.\",\"Add pineapple and tomatoes, simmer for 5 minutes.\",\"Add okra and fish fillets. Cook for 5-7 minutes until fish is cooked through and flaky.\",\"Stir in bean sprouts and cook for 1 minute. Remove from heat.\",\"Garnish with fresh herbs and sliced chili (if using).\",\"Serve hot with brown rice on the side.\"]},\"snack\":{\"name\":\"Protein Bar\",\"time\":\"3:30 PM\",\"description\":\"A convenient post-workout or mid-afternoon protein boost.\",\"foods\":[{\"name\":\"Standard Protein Bar\",\"amount\":\"1 bar (60g)\",\"calories\":200}],\"totalCalories\":200,\"macros\":{\"protein\":20,\"carbs\":20,\"fat\":8},\"instructions\":[\"Enjoy the protein bar as directed on the packaging.\"]}},\"dailyTotals\":{\"calories\":1319,\"protein\":103,\"carbs\":164,\"fat\":32}},{\"dayNumber\":6,\"date\":\"Day 6\",\"meals\":{\"breakfast\":{\"name\":\"Savory Oatmeal with Egg & Sautéed Mushrooms\",\"time\":\"7:00 AM\",\"description\":\"A unique and hearty savory twist on oatmeal, packed with protein and fiber.\",\"foods\":[{\"name\":\"Rolled Oats\",\"amount\":\"1/2 cup (40g)\",\"calories\":150},{\"name\":\"Water/Vegetable Broth\",\"amount\":\"1 cup (240ml)\",\"calories\":5},{\"name\":\"Large Egg\",\"amount\":\"1\",\"calories\":78},{\"name\":\"Mushrooms (sliced)\",\"amount\":\"1 cup (70g)\",\"calories\":15},{\"name\":\"Spinach\",\"amount\":\"1/2 cup (15g)\",\"calories\":4},{\"name\":\"Soy Sauce (low sodium)\",\"amount\":\"1 tsp (5ml)\",\"calories\":3},{\"name\":\"Sesame Oil\",\"amount\":\"1 tsp (5ml)\",\"calories\":40}],\"totalCalories\":295,\"macros\":{\"protein\":14,\"carbs\":33,\"fat\":13},\"instructions\":[\"Cook rolled oats with water or vegetable broth according to package directions. Keep warm.\",\"While oats are cooking, heat sesame oil in a small pan. Sauté mushrooms until tender. Add spinach and cook until wilted. Stir in soy sauce.\",\"Fry or poach the egg to your liking.\",\"Serve the savory oatmeal topped with sautéed mushrooms and spinach, and the cooked egg.\"]},\"lunch\":{\"name\":\"Grilled Chicken Skewers with Fresh Vermicelli Salad (Bun Ga Nuong inspired)\",\"time\":\"12:30 PM\",\"description\":\"A lighter take on a Vietnamese classic, focusing on lean protein and fresh herbs with less noodles.\",\"foods\":[{\"name\":\"Chicken Breast (cubed)\",\"amount\":\"120g\",\"calories\":198},{\"name\":\"Vermicelli Noodles (cooked)\",\"amount\":\"80g\",\"calories\":112},{\"name\":\"Lettuce (shredded)\",\"amount\":\"1 cup (30g)\",\"calories\":5},{\"name\":\"Cucumber (sliced)\",\"amount\":\"1/2 cup (50g)\",\"calories\":8},{\"name\":\"Carrots (julienned)\",\"amount\":\"1/4 cup (25g)\",\"calories\":10},{\"name\":\"Fresh Mint & Basil\",\"amount\":\"small handful\",\"calories\":2},{\"name\":\"Nuoc Cham (lightened dressing)\",\"amount\":\"3 tbsp (45ml)\",\"calories\":30},{\"name\":\"Olive Oil (for grilling)\",\"amount\":\"1 tsp (5ml)\",\"calories\":40}],\"totalCalories\":405,\"macros\":{\"protein\":34,\"carbs\":51,\"fat\":11},\"instructions\":[\"Marinate chicken cubes with a splash of fish sauce, garlic, and pepper for at least 15 minutes. Thread onto skewers.\",\"Grill or pan-fry chicken skewers until cooked through and lightly charred. (Can brush with a little olive oil).\",\"Prepare the salad: In a large bowl, combine cooked vermicelli noodles, shredded lettuce, cucumber, carrots, mint, and basil.\",\"Make lightened Nuoc Cham: Combine 1.5 tbsp fish sauce, 1.5 tbsp lime juice, 1 tsp sugar substitute or a tiny bit of honey, 2 tbsp water, and minced garlic/chili to taste.\",\"Serve grilled chicken skewers over the vermicelli salad, drizzled with Nuoc Cham.\"]},\"dinner\":{\"name\":\"Baked Cod with Steamed Green Beans & Quinoa\",\"time\":\"7:00 PM\",\"description\":\"A clean and simple meal, highlighting lean protein and whole grains.\",\"foods\":[{\"name\":\"Cod Fillet\",\"amount\":\"150g\",\"calories\":126},{\"name\":\"Cooked Quinoa\",\"amount\":\"150g\",\"calories\":190},{\"name\":\"Green Beans\",\"amount\":\"1.5 cups (150g)\",\"calories\":47},{\"name\":\"Olive Oil\",\"amount\":\"1.5 tbsp (22.5ml)\",\"calories\":180},{\"name\":\"Lemon Wedge\",\"amount\":\"1\",\"calories\":2}],\"totalCalories\":545,\"macros\":{\"protein\":33,\"carbs\":39,\"fat\":29},\"instructions\":[\"Preheat oven to 200°C (400°F).\",\"Place cod fillet on a baking sheet. Drizzle with 1/2 tbsp olive oil, season with salt, pepper, and a squeeze of lemon juice. Bake for 12-15 minutes, or until fish flakes easily.\",\"Cook quinoa according to package instructions.\",\"Steam green beans until tender-crisp (about 5-7 minutes). Toss with 1 tbsp olive oil, salt, and pepper.\",\"Serve baked cod with quinoa and steamed green beans.\"]},\"snack\":{\"name\":\"Rice Cakes with Peanut Butter & Banana Slices\",\"time\":\"3:30 PM\",\"description\":\"A quick and easy snack providing energy and some healthy fats.\",\"foods\":[{\"name\":\"Plain Rice Cakes\",\"amount\":\"2\",\"calories\":70},{\"name\":\"Peanut Butter (natural)\",\"amount\":\"1 tbsp (16g)\",\"calories\":95},{\"name\":\"Banana (sliced)\",\"amount\":\"1/2 medium (60g)\",\"calories\":53}],\"totalCalories\":218,\"macros\":{\"protein\":5,\"carbs\":30,\"fat\":10},\"instructions\":[\"Spread peanut butter evenly over rice cakes. Top with banana slices.\"]}},\"dailyTotals\":{\"calories\":1463,\"protein\":86,\"carbs\":153,\"fat\":63}},{\"dayNumber\":7,\"date\":\"Day 7\",\"meals\":{\"breakfast\":{\"name\":\"Spinach & Mushroom Omelette\",\"time\":\"7:00 AM\",\"description\":\"A classic high-protein breakfast, easy to customize.\",\"foods\":[{\"name\":\"Large Eggs\",\"amount\":\"2\",\"calories\":156},{\"name\":\"Egg Whites\",\"amount\":\"2\",\"calories\":34},{\"name\":\"Fresh Spinach\",\"amount\":\"1 cup (30g)\",\"calories\":7},{\"name\":\"Mushrooms (sliced)\",\"amount\":\"1/2 cup (35g)\",\"calories\":8},{\"name\":\"Olive Oil\",\"amount\":\"1 tsp (5ml)\",\"calories\":40}],\"totalCalories\":245,\"macros\":{\"protein\":23,\"carbs\":4,\"fat\":15},\"instructions\":[\"Heat olive oil in a non-stick pan over medium heat.\",\"Add mushrooms and spinach; sauté until mushrooms are tender and spinach wilts (2-3 minutes). Remove from pan and set aside.\",\"Whisk eggs and egg whites together in a bowl, season with salt and pepper.\",\"Pour egg mixture into the pan. Cook until the edges set (about 2 minutes). Gently push cooked egg from the edges towards the center, tilting the pan to allow uncooked egg to flow underneath.\",\"Once the top is mostly set but still slightly moist, spoon the cooked spinach and mushrooms onto one half of the omelette. Fold the other half over. Cook for another minute, then slide onto a plate.\"]},\"lunch\":{\"name\":\"Large Tuna Salad with Mixed Greens\",\"time\":\"12:30 PM\",\"description\":\"A quick and healthy lunch, packed with protein and vegetables.\",\"foods\":[{\"name\":\"Canned Tuna (in water, drained)\",\"amount\":\"150g\",\"calories\":180},{\"name\":\"Mixed Greens\",\"amount\":\"3 cups (90g)\",\"calories\":23},{\"name\":\"Cucumber (diced)\",\"amount\":\"1/2 cup (50g)\",\"calories\":8},{\"name\":\"Cherry Tomatoes (halved)\",\"amount\":\"1/2 cup (60g)\",\"calories\":11},{\"name\":\"Bell Pepper (diced)\",\"amount\":\"1/2 cup (75g)\",\"calories\":20},{\"name\":\"Red Onion (thinly sliced)\",\"amount\":\"1/4 cup (30g)\",\"calories\":12},{\"name\":\"Olive Oil\",\"amount\":\"1.5 tbsp (22.5ml)\",\"calories\":180},{\"name\":\"Red Wine Vinegar\",\"amount\":\"1 tbsp (15ml)\",\"calories\":3}],\"totalCalories\":437,\"macros\":{\"protein\":38,\"carbs\":19,\"fat\":28},\"instructions\":[\"Flake drained tuna into a bowl.\",\"In a large salad bowl, combine mixed greens, cucumber, cherry tomatoes, bell pepper, and red onion.\",\"Add flaked tuna to the salad.\",\"For the dressing: Whisk together olive oil and red wine vinegar. Season with salt and pepper.\",\"Pour dressing over the salad and toss gently to combine. Serve immediately.\"]},\"dinner\":{\"name\":\"Ca Kho To (Caramelized Fish) with Brown Rice & Steamed Broccoli\",\"time\":\"7:00 PM\",\"description\":\"A savory and slightly sweet Vietnamese classic, with lean fish and ample vegetables.\",\"foods\":[{\"name\":\"White Fish Fillet (e.g., Tilapia, Cod)\",\"amount\":\"150g\",\"calories\":130},{\"name\":\"Brown Rice\",\"amount\":\"120g cooked\",\"calories\":133},{\"name\":\"Broccoli Florets\",\"amount\":\"1.5 cups (135g)\",\"calories\":47},{\"name\":\"Fish Sauce\",\"amount\":\"1.5 tbsp (22.5ml)\",\"calories\":15},{\"name\":\"Stevia/Erythritol (sugar substitute)\",\"amount\":\"1 tsp\",\"calories\":0},{\"name\":\"Garlic (minced)\",\"amount\":\"2 cloves (6g)\",\"calories\":8},{\"name\":\"Green Onions (chopped)\",\"amount\":\"1 tbsp\",\"calories\":2},{\"name\":\"Olive Oil\",\"amount\":\"1 tsp (5ml)\",\"calories\":40}],\"totalCalories\":375,\"macros\":{\"protein\":34,\"carbs\":50,\"fat\":10},\"instructions\":[\"Cut fish into large pieces. In a small bowl, combine fish sauce, sugar substitute, garlic, and a splash of water (about 1 tbsp).\",\"Heat olive oil in a non-stick pot (a clay pot or small saucepan is traditional) over medium heat.\",\"Carefully add fish pieces to the pot. Pour the sauce mixture over the fish. Bring to a gentle simmer.\",\"Cover and cook for 10-12 minutes, gently turning the fish once, until fish is cooked through and sauce has thickened slightly. Garnish with green onions.\",\"While fish is cooking, steam broccoli until tender-crisp (5-7 minutes).\",\"Cook brown rice according to package instructions.\",\"Serve caramelized fish and sauce with brown rice and steamed broccoli.\"]},\"snack\":{\"name\":\"Walnuts & Orange\",\"time\":\"3:30 PM\",\"description\":\"A simple and nutritious snack providing healthy fats and Vitamin C.\",\"foods\":[{\"name\":\"Walnuts\",\"amount\":\"1/4 cup (28g)\",\"calories\":185},{\"name\":\"Small Orange\",\"amount\":\"1 (100g)\",\"calories\":47}],\"totalCalories\":232,\"macros\":{\"protein\":5,\"carbs\":12,\"fat\":19},\"instructions\":[\"Enjoy walnuts and orange together.\"]}},\"dailyTotals\":{\"calories\":1289,\"protein\":100,\"carbs\":85,\"fat\":72}}]',1924,'{\"protein\":{\"percentage\":25,\"grams\":120},\"carbs\":{\"percentage\":45,\"grams\":216},\"fat\":{\"percentage\":30,\"grams\":64}}','[]','{\"cuisine\":[],\"allergies\":[],\"mealsPerDay\":4}',0,1,'Goal: [\"weight_loss\",\"muscle_gain\"], Calories: 1924, Duration: 7 days, BMI: 20.8 (Normal)','2025-11-25 16:47:32','2025-11-25 16:49:20'),(4,3,'Thao\'s Body Recomposition Meal Plan','A 7-day meal plan designed for Thao Tran (21F, 158cm, 52kg, moderately active) with goals 