INSERT INTO `workout_plan_days` VALUES (29,2,1,'Week 1, Day 1 - Full Body Strength Foundation','Full Body Strength','[{\"exerciseId\":2,\"exerciseName\":\"Squats\",\"sets\":3,\"reps\":10,\"duration\":null,\"restSeconds\":90,\"notes\":\"Focus on controlled movement, keeping your chest up and core engaged.\"},{\"exerciseId\":1,\"exerciseName\":\"Push-ups\",\"sets\":3,\"reps\":8,\"duration\":null,\"restSeconds\":90,\"notes\":\"Perform on knees if regular push-ups are too challenging, maintaining good form.\"},{\"exerciseId\":54,\"exerciseName\":\"Face Pull\",\"sets\":3,\"reps\":12,\"duration\":null,\"restSeconds\":75,\"notes\":\"Focus on squeezing your upper back and rear shoulders, despite listed muscle groups.\"},{\"exerciseId\":4,\"exerciseName\":\"Plank\",\"sets\":3,\"reps\":null,\"duration\":30,\"restSeconds\":60,\"notes\":\"Keep your body in a straight line from head to heels, engage your core.\"},{\"exerciseId\":5,\"exerciseName\":\"Bicep Curls\",\"sets\":3,\"reps\":12,\"duration\":null,\"restSeconds\":75,\"notes\":\"Control the movement both up and down, avoid swinging.\"}]',50,300,'Warm up for 5-10 minutes with light cardio (e.g., jogging in place, arm circles) and dynamic stretches. Cool down for 5-10 minutes with static stretches.',0,1,'2025-11-25 13:39:51','2025-11-25 13:32:18','2025-11-25 13:39:51'),(30,2,2,'Week 1, Day 2 - Cardio & Core Blast','Cardiovascular & Core Endurance','[{\"exerciseId\":3,\"exerciseName\":\"Running\",\"sets\":null,\"reps\":null,\"duration\":20,\"restSeconds\":null,\"notes\":\"Maintain a steady, comfortable pace where you can hold a conversation.\"},{\"exerciseId\":19,\"exerciseName\":\"High Knees\",\"sets\":3,\"reps\":null,\"duration\":45,\"restSeconds\":60,\"notes\":\"Bring your knees as high as possible, pumping your arms. Perform as an interval.\"},{\"exerciseId\":18,\"exerciseName\":\"Burpees\",\"sets\":3,\"reps\":8,\"duration\":null,\"restSeconds\":90,\"notes\":\"Focus on the full movement. Take a step back with your feet if jumping is too much initially.\"},{\"exerciseId\":4,\"exerciseName\":\"Plank\",\"sets\":3,\"reps\":null,\"duration\":30,\"restSeconds\":60,\"notes\":\"Keep core tight and body straight.\"}]',40,250,'Warm up for 5 minutes with light dynamic movements. Cool down for 5 minutes with light stretching, focusing on legs and core.',0,0,NULL,'2025-11-25 13:32:18','2025-11-25 13:32:18'),(31,2,3,'Week 1, Day 3 - Rest and Recovery','Recovery','[]',0,0,'Prioritize active recovery such as a leisurely walk, gentle stretching, or foam rolling. Focus on hydration and nutrient-rich foods.',1,0,NULL,'2025-11-25 13:32:18','2025-11-25 13:32:18'),(32,2,4,'Week 1, Day 4 - Full Body Strength II','Full Body Strength','[{\"exerciseId\":35,\"exerciseName\":\"Split Squat\",\"sets\":3,\"reps\":8,\"duration\":null,\"restSeconds\":90,\"notes\":\"8 reps per leg. Maintain balance and a controlled descent. Despite listed muscles, this is for legs.\"},{\"exerciseId\":32,\"exerciseName\":\"Shoulder Press\",\"sets\":3,\"reps\":10,\"duration\":null,\"restSeconds\":75,\"notes\":\"Use light weight or bodyweight (e.g., pike push-ups variation). Focus on pushing vertically. Targets shoulders and triceps.\"},{\"exerciseId\":25,\"exerciseName\":\"Squat\",\"sets\":3,\"reps\":10,\"duration\":null,\"restSeconds\":90,\"notes\":\"Focus on engaging your glutes and quads. This is a primary lower body exercise.\"},{\"exerciseId\":49,\"exerciseName\":\"Cable Tricep Pushdown\",\"sets\":3,\"reps\":12,\"duration\":null,\"restSeconds\":75,\"notes\":\"Keep elbows close to your body and focus on contracting the triceps.\"},{\"exerciseId\":47,\"exerciseName\":\"Glute Stretch\",\"sets\":2,\"reps\":null,\"duration\":30,\"restSeconds\":30,\"notes\":\"Hold each stretch for 20-30 seconds per side. Great for hip mobility and recovery.\"}]',50,300,'Warm up for 5-10 minutes with light cardio and dynamic stretches. Cool down for 5-10 minutes with static stretches, especially for the lower body.',0,0,NULL,'2025-11-25 13:32:18','2025-1